package com.trustvault.document;

import com.trustvault.common.CurrentUser; import com.trustvault.user.*; import jakarta.validation.constraints.NotBlank;
import org.springframework.core.io.Resource; import org.springframework.security.access.AccessDeniedException; import org.springframework.http.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import jakarta.validation.Valid;
import java.time.LocalDate; import java.util.*;

@Controller @RequestMapping("/documents")
public class DocumentController {
 private final DocumentService service;private final AppUserRepository users;private final CurrentUser current;
 public DocumentController(DocumentService service,AppUserRepository users,CurrentUser current){this.service=service;this.users=users;this.current=current;}
 @GetMapping public String list(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)String owner,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to,Model model){model.addAttribute("documents",service.search(q,category,owner,from,to));model.addAttribute("q",q);model.addAttribute("category",category);model.addAttribute("owner",owner);model.addAttribute("from",from);model.addAttribute("to",to);model.addAttribute("canUpload",current.get().getRole()!=Role.VIEWER);return "documents/list";}
 @GetMapping("/new") public String newForm(Model m){if(current.get().getRole()==Role.VIEWER)return "redirect:/documents?denied";m.addAttribute("form",new DocumentForm());return "documents/form";}
 @PostMapping public String upload(@Valid @ModelAttribute("form")DocumentForm form,BindingResult result,Model model){if(result.hasErrors()){return "documents/form";}try{service.upload(form.file,form.title,form.description,form.category);return "redirect:/documents?uploaded";}catch(AccessDeniedException e){throw e;}catch(IllegalArgumentException e){model.addAttribute("error",e.getMessage());return "documents/form";}}
 @GetMapping("/{id}") public String detail(@PathVariable UUID id,Model model){VaultDocument d=service.getReadable(id);model.addAttribute("document",d);model.addAttribute("canManage",current.get().getRole()==Role.ADMIN||d.getOwner().getId().equals(current.get().getId()));model.addAttribute("canEdit",current.get().getRole()==Role.ADMIN||d.getOwner().getId().equals(current.get().getId())||service.sharesForCurrentUserCanEdit(id));if(model.getAttribute("canManage").equals(true)) {model.addAttribute("shares",service.shares(id));model.addAttribute("employees",users.findByEnabledTrueAndIdNotOrderByFullNameAsc(d.getOwner().getId()));model.addAttribute("accessLevels",AccessLevel.values());}return "documents/detail";}
 @GetMapping("/{id}/edit") public String edit(@PathVariable UUID id,Model m){VaultDocument d=service.getReadable(id);if(!service.sharesForCurrentUserCanEdit(id))throw new org.springframework.security.access.AccessDeniedException("You cannot edit this document");DocumentForm f=new DocumentForm();f.title=d.getTitle();f.description=d.getDescription();f.category=d.getCategory();m.addAttribute("form",f);m.addAttribute("document",d);return "documents/edit";}
 @PostMapping("/{id}/edit") public String update(@PathVariable UUID id,@Valid @ModelAttribute DocumentForm form,BindingResult result){if(result.hasErrors()) return "redirect:/documents/"+id+"/edit?invalid"; service.update(id,form.title,form.description,form.category);return "redirect:/documents/"+id+"?updated";}
 @PostMapping("/{id}/delete") public String delete(@PathVariable UUID id){service.delete(id);return "redirect:/documents?deleted";}
 @GetMapping("/{id}/download") public ResponseEntity<Resource> download(@PathVariable UUID id){DocumentService.DownloadedFile f=service.download(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.contentType())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(f.filename(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").body(f.resource());}
 @PostMapping("/{id}/shares") public String grant(@PathVariable UUID id,@RequestParam UUID userId,@RequestParam AccessLevel accessLevel){service.grant(id,userId,accessLevel);return "redirect:/documents/"+id+"?shared";}
 @PostMapping("/{id}/shares/{userId}/revoke") public String revoke(@PathVariable UUID id,@PathVariable UUID userId){service.revoke(id,userId);return "redirect:/documents/"+id+"?revoked";}
 public static class DocumentForm { @NotBlank public String title; public String description; @NotBlank public String category; public MultipartFile file; }
}
